contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "test cannot send amount");

        uint256 beforeC = address(c).balance;
        uint256 beforeU = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterU = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted == false && afterC == beforeC + amount && afterU == beforeU + amount);
    }

    receive() external payable {}
}

